window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-74cb2b84a8142c7a"]={"versions": [{"id": "FIG-74cb2b84a8142c7a", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der E2E-Profil-7m-Prüffunktion (<code>E2E_P07mCheck</code>) auf Client-Seite innerhalb der AUTOSAR-E2E-Bibliothek (End-to-End Communication Protection).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionsschnittstelle:</strong> <code>E2E_P07mCheck(Config, State, SourceID, MessageTyp, MessageResult, Data, Length)</code>\n</li><li><strong>Aktionen (Sub-Aktivitäten mit Aufrufsymbol):</strong>\n<ul class=\"fig-list\"><li><code>Verify inputs of the check function</code>\n</li><li><code>Compute offset</code>\n</li><li><code>Read Length</code>\n</li><li><code>Read Counter</code>\n</li><li><code>Read DataID</code>\n</li><li><code>Read SourceID</code>\n</li><li><code>Read Message Type</code>\n</li><li><code>Read Message Result</code>\n</li><li><code>Read CRC</code>\n</li><li><code>Compute CRC</code>\n</li><li><code>Do checks</code>\n</li></ul>\n</li><li><strong>Knoten &amp; Verzweigungen:</strong>\n<ul class=\"fig-list\"><li>Initialknoten (Start)\n</li><li>Entscheidungsknoten <code>NewDataAvailable == TRUE</code> mit Guards <code>[TRUE]</code> und <code>[FALSE]</code>\n</li><li>Drei Aktivitätsendknoten mit Rückgaben (<code>return</code>) für die Pfade <code>[null input]</code>, <code>[input ok]</code> (regulärer Pfad) und <code>[wrong input]</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start am Initialknoten und Übergang zur Prüfung der Eingabeparameter in <code>Verify inputs of the check function</code>.\n</li><li>Bei ungültigen Zeigern (<code>[null input]</code>) verzweigt der Kontrollfluss direkt zum linken Endknoten.\n</li><li>Bei fehlerhaften Eingabewerten (<code>[wrong input]</code>) verzweigt der Kontrollfluss direkt zum rechten Endknoten.\n</li><li>Bei fehlerfreien Parametern (<code>[input ok]</code>) erfolgt die Auswertung der Bedingung <code>NewDataAvailable == TRUE</code>:\n<ul class=\"fig-list\"><li>Falls <code>[TRUE]</code>: Sequenzielle Ausführung von <code>Compute offset</code> -&gt; <code>Read Length</code> -&gt; <code>Read Counter</code> -&gt; <code>Read DataID</code> -&gt; <code>Read SourceID</code> -&gt; <code>Read Message Type</code> -&gt; <code>Read Message Result</code> -&gt; <code>Read CRC</code> -&gt; <code>Compute CRC</code> -&gt; <code>Do checks</code>.\n</li><li>Falls <code>[FALSE]</code>: Umgehung der Lese- und CRC-Berechnungsschritte über einen Bypass direkt zu <code>Do checks</code>.\n</li></ul>\n</li><li>Nach Abschluss von <code>Do checks</code> terminiert die Funktion am mittleren Endknoten (<code>return</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das übergeordnete normative Verhalten von <code>[PRS_E2E_00815]</code> für die Client-Überladung von E2E Profile 7m. Es legt die zwingende Reihenfolge bei der Extraktion der Header-Felder (Length, Counter, DataID, SourceID, Message Type, Message Result, CRC) sowie die Bedingungsprüfung für neu verfügbare Daten (<code>NewDataAvailable</code>) fest. Bei Fehlen neuer Daten (<code>[FALSE]</code>) dürfen keine Header-Felder gelesen oder CRCs berechnet werden; stattdessen ist direkt die Zustandsauswertung in <code>Do checks</code> anzusteuern. Die Sub-Aktivitäten sind in nachfolgenden Spezifikationsschritten separat detailliert.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-3246c296eb878001", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der E2E-Profil-7m-Prüffunktion (<code>E2E_P07mCheck</code>) auf Client-Seite innerhalb der AUTOSAR-E2E-Bibliothek (End-to-End Communication Protection).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionsschnittstelle:</strong> <code>E2E_P07mCheck(Config, State, SourceID, MessageTyp, MessageResult, Data, Length)</code>\n</li><li><strong>Aktionen (Sub-Aktivitäten mit Aufrufsymbol):</strong>\n<ul class=\"fig-list\"><li><code>Verify inputs of the check function</code>\n</li><li><code>Compute offset</code>\n</li><li><code>Read Length</code>\n</li><li><code>Read Counter</code>\n</li><li><code>Read DataID</code>\n</li><li><code>Read SourceID</code>\n</li><li><code>Read Message Type</code>\n</li><li><code>Read Message Result</code>\n</li><li><code>Read CRC</code>\n</li><li><code>Compute CRC</code>\n</li><li><code>Do checks</code>\n</li></ul>\n</li><li><strong>Knoten &amp; Verzweigungen:</strong>\n<ul class=\"fig-list\"><li>Initialknoten (Start)\n</li><li>Entscheidungsknoten <code>NewDataAvailable == TRUE</code> mit Guards <code>[TRUE]</code> und <code>[FALSE]</code>\n</li><li>Drei Aktivitätsendknoten mit Rückgaben (<code>return</code>) für die Pfade <code>[null input]</code>, <code>[input ok]</code> (regulärer Pfad) und <code>[wrong input]</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start am Initialknoten und Übergang zur Prüfung der Eingabeparameter in <code>Verify inputs of the check function</code>.\n</li><li>Bei ungültigen Zeigern (<code>[null input]</code>) verzweigt der Kontrollfluss direkt zum linken Endknoten.\n</li><li>Bei fehlerhaften Eingabewerten (<code>[wrong input]</code>) verzweigt der Kontrollfluss direkt zum rechten Endknoten.\n</li><li>Bei fehlerfreien Parametern (<code>[input ok]</code>) erfolgt die Auswertung der Bedingung <code>NewDataAvailable == TRUE</code>:\n<ul class=\"fig-list\"><li>Falls <code>[TRUE]</code>: Sequenzielle Ausführung von <code>Compute offset</code> -&gt; <code>Read Length</code> -&gt; <code>Read Counter</code> -&gt; <code>Read DataID</code> -&gt; <code>Read SourceID</code> -&gt; <code>Read Message Type</code> -&gt; <code>Read Message Result</code> -&gt; <code>Read CRC</code> -&gt; <code>Compute CRC</code> -&gt; <code>Do checks</code>.\n</li><li>Falls <code>[FALSE]</code>: Umgehung der Lese- und CRC-Berechnungsschritte über einen Bypass direkt zu <code>Do checks</code>.\n</li></ul>\n</li><li>Nach Abschluss von <code>Do checks</code> terminiert die Funktion am mittleren Endknoten (<code>return</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das übergeordnete normative Verhalten von <code>[PRS_E2E_00815]</code> für die Client-Überladung von E2E Profile 7m. Es legt die zwingende Reihenfolge bei der Extraktion der Header-Felder (Length, Counter, DataID, SourceID, Message Type, Message Result, CRC) sowie die Bedingungsprüfung für neu verfügbare Daten (<code>NewDataAvailable</code>) fest. Bei Fehlen neuer Daten (<code>[FALSE]</code>) dürfen keine Header-Felder gelesen oder CRCs berechnet werden; stattdessen ist direkt die Zustandsauswertung in <code>Do checks</code> anzusteuern. Die Sub-Aktivitäten sind in nachfolgenden Spezifikationsschritten separat detailliert.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-74cb2b84a8142c7a", "to": "FIG-3246c296eb878001", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
